We implement the dispatch loop that runs until the model produces a final text response:

def run_tool_loop(
    messages: list[dict],
    tools: list[dict],
    tool_registry: dict,
) -&gt; str:
    """Run tool calls until the model produces a final text response."""
    messages = list(messages)  # don't mutate the caller's list
    while True:
        response = client.chat.completions.create(
            model="gpt-4o-mini",
            messages=messages,
            tools=tools,
            temperature=0.0,
        )
        msg = response.choices[0].message
1        if response.choices[0].finish_reason != "tool_calls":
            return msg.content
2        messages.append(msg)
        for tc in msg.tool_calls:
            fn = tool_registry[tc.function.name]
            args = json.loads(tc.function.arguments)
            result = fn(**args)
3            messages.append({
                "role": "tool",
                "tool_call_id": tc.id,
                "content": json.dumps(result),
            })

answer = run_tool_loop(
    messages=[{"role": "user", "content": "What is the current price of AAPL?"}],
    tools=TOOLS,
    tool_registry={"get_stock_price": get_stock_price},
)
print(answer)


1

Loop until finish_reason is not "tool_calls" — meaning the model has synthesized a final natural-language response.

2

Append the assistant’s tool-call message to maintain the full conversation state before the next turn.

3

Each tool result is appended as a "tool" role message keyed by tool_call_id, so the model knows which call this result answers.

Tool Registry
We need a uniform interface for tools: each tool has a name, a description (which the model reads to decide whether to use it), a JSON Schema for its parameters, and a Python callable. We wrap these in a Tool dataclass and a ToolRegistry that translates the registry into the list-of-dicts format the OpenAI API expects.

from dataclasses import dataclass
from typing import Callable, Any


@dataclass
class Tool:
    name: str
    description: str
    parameters: dict  # JSON Schema object
    fn: Callable[..., Any]


class ToolRegistry:
    """Registry translating Tool objects into OpenAI function-calling format."""

    def __init__(self):
        self._tools: dict[str, Tool] = {}

    def register(self, tool: Tool) -&gt; None:
        self._tools[tool.name] = tool

1    def get_schema(self) -&gt; list[dict]:
        """Return the list of tool dicts for the OpenAI tools parameter."""
        return [
            {
                "type": "function",
                "function": {
                    "name": t.name,
                    "description": t.description,
                    "parameters": t.parameters,
                },
            }
            for t in self._tools.values()
        ]

2    def call(self, name: str, arguments: str) -&gt; str:
        """Execute the named tool with JSON-encoded arguments."""
        if name not in self._tools:
            return f"Error: unknown tool '{name}'"
        kwargs = json.loads(arguments)
        try:
            result = self._tools[name].fn(**kwargs)
            return json.dumps(result) if not isinstance(result, str) else result
        except Exception as e:
            return f"Error executing {name}: {e}"


1

get_schema produces the exact format the OpenAI tools parameter expects — a list of objects each with type: "function" and a nested function dict containing name, description, and parameters (JSON Schema).

2

call deserializes the JSON-encoded arguments string that the model emits, invokes the Python callable, and serializes the result back to a string for the tool role message.




